static const int ITEM_NAMES_N = 23548;

// English name for an item id, or 0 if unknown.
inline const char* item_name(unsigned id) {
    int lo = 0, hi = ITEM_NAMES_N - 1;
    while (lo <= hi) { const int mid = (lo + hi) >> 1; const unsigned m = ITEM_NAMES[mid].id;
        if (m == id) return ITEM_NAMES[mid].en; if (m < id) lo = mid + 1; else hi = mid - 1; }
    return 0;
}

