static const int ITEM_DISPLAY_N = 20276;
inline const char* item_display_name(unsigned id) {
    int lo = 0, hi = ITEM_DISPLAY_N - 1;
    while (lo <= hi) { const int mid = (lo + hi) >> 1; const unsigned m = ITEM_DISPLAY[mid].id;
        if (m == id) return ITEM_DISPLAY[mid].en; if (m < id) lo = mid + 1; else hi = mid - 1; }
    return item_name(id);
}

